 * 流程：凍結玩家 → 黑幕祈禱文字 → 魔法陣 + 天降光束 → 電腦當機
 */
function triggerHolyCinematic(scene, playerSprite, yeahSprite) {
    const width = scene.cameras.main.width;
    const height = scene.cameras.main.height;

    // === 第一階段：凍結玩家、清除場上能量球 ===
    playerSprite.setVelocity(0, 0);
    playerSprite.body.allowGravity = false; // 暫時取消重力讓玩家定住
    playerState.isInvincible = true;        // 動畫期間無敵

    // 清除場上殘留的能量球
    if (yeahEnergyBalls) yeahEnergyBalls.clear(true, true);

    // 凍結顏王Yeah 的移動
    if (yeahSprite && yeahSprite.active) {
        yeahSprite.setVelocity(0, 0);
        yeahSprite.body.allowGravity = false;
    }

    // === 第二階段：黑幕遮罩 + 祈禱文字逐行顯示 ===
    const overlay = scene.add.rectangle(width / 2, height / 2, width, height, 0x000000, 0);
    overlay.setDepth(9998);

    // 淡入黑幕
    scene.tweens.add({
        targets: overlay,
        alpha: 0.85,
        duration: 500,
        onComplete: () => {
            // 祈禱文字的五行內容
            const lines = [
                '在此為胖嘟嘟發電機獻上祈禱',
                '請賜予我聖靈之力',
                '傾聽我的願望',
                '萬物歸盡',
                '顏值崩壞'
            ];

            let currentLine = 0;

            // 逐行顯示函式
            const showNextLine = () => {
                if (currentLine >= lines.length) {
                    // 所有文字顯示完畢，進入第三階段
                    scene.time.delayedCall(500, () => {
                        // 淡出黑幕
                        scene.tweens.add({
                            targets: overlay,
                            alpha: 0,
                            duration: 300,
                            onComplete: () => {
                                overlay.destroy();
                                // 進入魔法陣 + 光束階段
                                triggerDivineBeam(scene, playerSprite, yeahSprite);
                            }
                        });
                    });
                    return;
                }

                const isLastLine = currentLine === lines.length - 1;
                const displayDuration = isLastLine ? 2000 : 1000; // 最後一行顯示 2 秒

                // 建立祈禱文字 (置中螢幕)
                const textStyle = {
                    fontSize: isLastLine ? '52px' : '36px', // 最後一行放大字型
                    fill: '#ffd700',
                    fontStyle: 'bold',
                    stroke: isLastLine ? '#ffaa00' : '#000',
                    strokeThickness: isLastLine ? 6 : 4,
                    padding: { left: 10, right: 10, top: 10, bottom: 10 }
                };

                // 如果是最後一行，加入金色光暈陰影效果
                if (isLastLine) {
                    textStyle.shadow = {
                        color: '#ffd700',
                        fill: true,
                        offsetX: 0,
                        offsetY: 0,
                        blur: 25
                    };
                }

                const lineText = scene.add.text(width / 2, height / 2, lines[currentLine], textStyle)
                    .setOrigin(0.5)
                    .setDepth(9999)
                    .setAlpha(0);

                // 淡入文字
                scene.tweens.add({
                    targets: lineText,
                    alpha: 1,
                    duration: 300,
                    onComplete: () => {
                        // 如果是最後一行，加入字型放大的強調動畫
                        if (isLastLine) {
                            scene.tweens.add({
                                targets: lineText,
                                scaleX: 1.3,
                                scaleY: 1.3,
                                duration: 800,
                                ease: 'Sine.easeInOut',
                                yoyo: true
                            });
                        }

                        // 等待指定時間後淡出並顯示下一行
                        scene.time.delayedCall(displayDuration, () => {
                            scene.tweens.add({
                                targets: lineText,
                                alpha: 0,
                                duration: 200,
                                onComplete: () => {
                                    lineText.destroy();
                                    currentLine++;
                                    showNextLine();
                                }
                            });
                        });
                    }
                });
            };

            // 開始顯示第一行
            showNextLine();
        }
    });
}

/**
 * 神聖光束攻擊 ── 祈禱文字結束後觸發
 * 流程：生成玩家上下的黃色魔法陣 → 天降金色巨大光束 2 秒 → 觸發當機
 */
function triggerDivineBeam(scene, playerSprite, yeahSprite) {
    const width = scene.cameras.main.width;
    const height = scene.cameras.main.height;
    const px = playerSprite.x;
    const py = playerSprite.y;

    // 恢復顏王Yeah 重力（讓他恢復正常動作）
    if (yeahSprite && yeahSprite.active) {
        yeahSprite.body.allowGravity = true;
    }

    // === 玩家上下生成黃色魔法陣 ===
    const magicCircles = [];
    const circleCount = 6; // 上下各 3 個魔法陣

    for (let i = 0; i < circleCount; i++) {
        const isTop = i < circleCount / 2;
        const yOffset = isTop ? -80 - i * 40 : 80 + (i - circleCount / 2) * 40;
        const radius = 50 + i * 15;

        // 使用 Graphics 繪製魔法陣圓環
        const circle = scene.add.graphics();
        circle.setDepth(9990);

        // 外圈
        circle.lineStyle(3, 0xffd700, 0.9);
        circle.strokeCircle(px, py + yOffset, radius);
        // 內圈
        circle.lineStyle(2, 0xffaa00, 0.6);
        circle.strokeCircle(px, py + yOffset, radius * 0.6);
        // 核心圈
        circle.lineStyle(1, 0xffffff, 0.5);
        circle.strokeCircle(px, py + yOffset, radius * 0.3);

        circle.setAlpha(0);
        magicCircles.push(circle);

        // 淡入魔法陣
        scene.tweens.add({
            targets: circle,
            alpha: 1,
            duration: 400,
            delay: i * 100 // 依序淡入
        });
    }

    // 螢幕閃白代表魔法蓄力完成
    scene.time.delayedCall(800, () => {
        scene.cameras.main.flash(300, 255, 255, 200, false);
    });

    // === 1 秒後天降巨大金色光束打在玩家身上，持續 2 秒 ===
    scene.time.delayedCall(1000, () => {
        // 建立光束 Graphics
        const beam = scene.add.graphics();
        beam.setDepth(9991);

        // 繪製從天花板到玩家位置的巨大光束 (寬度 80px 的金色半透明矩形)
        const beamWidth = 80;
        const beamX = px - beamWidth / 2;

        // 光束主體 (金黃色半透明)
        beam.fillStyle(0xffd700, 0.7);
        beam.fillRect(beamX, 0, beamWidth, py + 50);
        // 光束核心 (更亮的白金色)
        beam.fillStyle(0xffffff, 0.4);
        beam.fillRect(beamX + 15, 0, beamWidth - 30, py + 50);
        // 光束外層擴散 (淡金色)
        beam.fillStyle(0xffd700, 0.2);
        beam.fillRect(beamX - 20, 0, beamWidth + 40, py + 50);

        beam.setAlpha(0);

        // 光束淡入動畫
        scene.tweens.add({
            targets: beam,
            alpha: 1,
            duration: 200
        });

        // 光束閃爍脈衝效果
        scene.tweens.add({
            targets: beam,
            alpha: { from: 0.8, to: 1.0 },
            duration: 150,
            yoyo: true,
            repeat: 6,
            delay: 200
        });

        // 螢幕持續震動代表衝擊
        scene.cameras.main.shake(2000, 0.01);

        // 2 秒後清除光束與魔法陣，觸發當機畫面
        scene.time.delayedCall(2000, () => {
            // 清除所有魔法陣
            magicCircles.forEach(c => { if (c && c.active) c.destroy(); });

            // 淡出光束
            scene.tweens.add({
                targets: beam,
                alpha: 0,
                duration: 200,
                onComplete: () => {
                    beam.destroy();

                    // 恢復玩家重力 (雖然馬上要當機了)
                    playerSprite.body.allowGravity = true;
                    playerState.isInvincible = false;

                    // 觸發電腦當機畫面 (force = true 強制當機，無視無敵)
                    if (scene.triggerCrash) {
                        scene.triggerCrash(true);
                    }
                }
            });
        });
    });
}

