        });
    }

    // 螢幕閃白代表魔法蓄力完成
    scene.time.delayedCall(800, () => {
        scene.cameras.main.flash(300, 255, 255, 200, false);
    });

    // === 1 秒後天降巨大金色光束打在玩家身上，持續 4 秒 (拉長生存衝擊感) ===
