        scene.cameras.main.shake(2000, 0.01);

        // 2 秒後清除光束與魔法陣，觸發當機畫面
        scene.time.delayedCall(2000, () => {
            // 清除所有魔法陣
            magicCircles.forEach(c => { if (c && c.active) c.destroy(); });

