        // 光束閃爍脈衝效果 (延長為 4 秒)
        scene.tweens.add({
            targets: beam,
            alpha: { from: 0.7, to: 1.0 },
            duration: 150,
            yoyo: true,
            repeat: 24, // 增加脈衝閃爍次數
            delay: 200
        });

        // 螢幕持續震動代表強烈衝擊 (延長為 4 秒)
        scene.cameras.main.shake(4000, 0.015);

        // 4 秒後清除光束與魔法陣，觸發當機畫面
        scene.time.delayedCall(4000, () => {
            // 清除所有魔法陣及鎖鏈
            magicCircles.forEach(c => { if (c && c.active) c.destroy(); });

