    // === 第二階段：黑幕遮罩 (完全黑色) + 祈禱文字逐行顯示 ===
    // 必須將 fillAlpha 設為 1.0，改由 GameObject 的 alpha 控制淡入，否則填滿透明度為 0 時即使改變 global alpha 也依然透明
    const overlay = scene.add.rectangle(width / 2, height / 2, width, height, 0x000000, 1.0);
    overlay.setAlpha(0); // 初始全透明
    overlay.setDepth(9998);

    // 淡入黑幕到完全黑色 (不透明度 1.0)
    scene.tweens.add({
        targets: overlay,
        alpha: 1.0,
        duration: 500,
        onComplete: () => {
            // 祈禱文字的五行內容
            const lines = [
                '在此為胖嘟嘟發電機獻上祈禱',
                '請賜予我聖靈之力',
                '傾聽我的願望',
                '萬物歸盡',
                '顏值崩壞'
            ];

            let currentLine = 0;

            // 逐行顯示函式
            const showNextLine = () => {
                if (currentLine >= lines.length) {
                    // 所有文字顯示完畢，進入第三階段
                    scene.time.delayedCall(500, () => {
                        // 淡出黑幕
                        scene.tweens.add({
                            targets: overlay,
                            alpha: 0,
                            duration: 300,
                            onComplete: () => {
                                overlay.destroy();
