                    fill: '#ffd700',
                    fontStyle: 'bold',
                    stroke: isLastLine ? '#ffaa00' : '#000',
                    strokeThickness: isLastLine ? 15 : 10, // 配合大字體加粗邊框
                    padding: { left: 20, right: 20, top: 20, bottom: 20 }
                };

