                if (isLastLine) {
                    textStyle.shadow = {
                        color: '#ffd700',
                        fill: true,
                        offsetX: 0,
                        offsetY: 0,
                        blur: 35
                    };
                }

                const lineText = scene.add.text(width / 2, height / 2, lines[currentLine], textStyle)
                    .setOrigin(0.5)
                    .setDepth(9999)
                    .setAlpha(0);

                // 淡入文字
                scene.tweens.add({
                    targets: lineText,
                    alpha: 1,
                    duration: 300,
                    onComplete: () => {
                        // 如果是最後一行，加入字型放大的強調動畫
                        if (isLastLine) {
                            scene.tweens.add({
                                targets: lineText,
                                scaleX: 1.3,
                                scaleY: 1.3,
                                duration: 800,
                                ease: 'Sine.easeInOut',
                                yoyo: true
                            });
                        }

                        // 等待指定時間後淡出並顯示下一行
                        scene.time.delayedCall(displayDuration, () => {
                            scene.tweens.add({
                                targets: lineText,
                                alpha: 0,
                                duration: 200,
                                onComplete: () => {
                                    lineText.destroy();
                                    currentLine++;
                                    showNextLine();
                                }
                            });
                        });
                    }
                });
            };

            // 開始顯示第一行
            showNextLine();
        }
    });
}

