    const chainGfx = scene.add.graphics();
    chainGfx.setDepth(9989); // 位於魔法陣正下方
    chainGfx.setAlpha(0);

    // 繪製單條鎖鏈的輔助函式 (由多個小橢圓環扣環組成)
    const drawChainLink = (x1, y1, x2, y2) => {
        const dist = Phaser.Math.Distance.Between(x1, y1, x2, y2);
        const steps = Math.max(5, Math.floor(dist / 14));
        for (let s = 0; s <= steps; s++) {
            const t = s / steps;
            const cx = x1 + (x2 - x1) * t;
            const cy = y1 + (y2 - y1) * t;
            chainGfx.lineStyle(3, 0x888888, 0.85); // 鋼鐵灰環
            chainGfx.strokeEllipse(cx, cy, 14, 8);
            chainGfx.lineStyle(1, 0xffffff, 0.4);  // 鏈條反射高光
            chainGfx.strokeEllipse(cx, cy, 10, 5);
        }
    };

    // 均勻分佈 5 個方向的鎖鏈角度
    const angles = [
        0,                 // 右
        0.4 * Math.PI,     // 右下
        0.8 * Math.PI,     // 左下
        1.2 * Math.PI,     // 左上
        1.6 * Math.PI      // 右上
    ];

    angles.forEach(angle => {
        // 鎖鏈起點為地面魔法陣的外邊界點
        const xStart = px + (groundWidth / 2) * Math.cos(angle);
        const yStart = (py + groundYOffset) + (groundHeight / 2) * Math.sin(angle);

        // 鎖鏈終點朝外斜向下伸展，鎖定入地面/虛空中
        const xEnd = xStart + Math.cos(angle) * 160;
        const yEnd = yStart + Math.abs(Math.sin(angle)) * 80;

        drawChainLink(xStart, yStart, xEnd, yEnd);
    });

    magicCircles.push(chainGfx); // 將鎖鏈元件加入清除清單，在結束時一併銷毀

    // 鎖鏈淡入動畫
    scene.tweens.add({
        targets: chainGfx,
        alpha: 1,
        duration: 500,
        delay: 600
    });

    // 螢幕閃白代表魔法蓄力完成
    scene.time.delayedCall(800, () => {
        scene.cameras.main.flash(300, 255, 255, 200, false);
    });

