            yoyo: true,
            repeat: 24, // 增加脈衝閃爍次數
            delay: 200
        });

        // 螢幕持續震動代表強烈衝擊 (延長為 4 秒)
        scene.cameras.main.shake(4000, 0.015);

        // 4 秒後清除光束與魔法陣，觸發當機畫面
        scene.time.delayedCall(4000, () => {
            // 清除所有魔法陣及鎖鏈
            magicCircles.forEach(c => { if (c && c.active) c.destroy(); });

            // 淡出光束
            scene.tweens.add({
                targets: beam,
                alpha: 0,
                duration: 200,
                onComplete: () => {
                    beam.destroy();

                    // 恢復玩家重力 (雖然馬上要當機了)
                    playerSprite.body.allowGravity = true;
                    playerState.isInvincible = false;

                    // 觸發電腦當機畫面 (force = true 強制當機，無視無敵)
                    if (scene.triggerCrash) {
                        scene.triggerCrash(true);
                    }
                }
            });
        });
