/**
 * 死亡選擇畫面 ── 玩家被光束擊碎後觸發
 * 流程：暫停遊戲 → 進入全黑背景 → 打字機效果字體 → 提供「當機」與「死亡」兩個按鈕
 */
function showDeathSelectionScreen(scene) {
    // 暫停遊戲物理與場景
    if (scene.physics) {
        scene.physics.pause();
    }
    scene.scene.pause();

    // 建立黑色背景的全螢幕 DOM 容器
    const selectContainer = document.createElement('div');
    selectContainer.className = 'death-select-container';

    // 直接套用 inline style 確保跨平台/跨瀏覽器視覺效果一致且免除快取問題
    Object.assign(selectContainer.style, {
        position: 'fixed',
        top: '0',
        left: '0',
        width: '100vw',
        height: '100vh',
        backgroundColor: '#000000', // 全黑背景
        color: '#ffd700', // 金黃色文字
        fontFamily: "'Courier New', Courier, monospace, 'Microsoft JhengHei', sans-serif",
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        zIndex: '10005', // 高於一切 Dom 層級
        padding: '40px',
        boxSizing: 'border-box'
    });

    // 建立文字內容容器
    const textElement = document.createElement('div');
    Object.assign(textElement.style, {
        fontSize: '28px',
        lineHeight: '1.6',
        maxWidth: '800px',
        textAlign: 'center',
