    let index = 0;

    const typeWriter = () => {
        if (index < fullText.length) {
            textElement.textContent += fullText.charAt(index);
            index++;
            setTimeout(typeWriter, 50); // 每 50 毫秒打一個字
        } else {
            // 打字完畢後漸顯按鈕容器
