        selectContainer.remove();
        if (scene.triggerCrash) {
            scene.triggerCrash(true);
        }
    };

    // 秘技：冥王炮點擊事件！
    plutoBtn.onclick = () => {
        // 1. 移除選擇容器，重返戰場
        selectContainer.remove();

        // 2. 恢復遊戲物理與場景
        if (scene.physics) {
            scene.physics.resume();
        }
        scene.scene.resume();

        // 3. 恢復玩家重力與無敵防護時間 (持續 3 秒，避免重生瞬間暴斃)
        if (player && player.body) {
            player.body.allowGravity = true;
        }
        playerState.isInvincible = true;
        scene.time.delayedCall(3000, () => {
            playerState.isInvincible = false;
        });

        // 4. 重置必殺動畫狀態標記，讓更新與控制回歸正常
        scene.isCinematicActive = false;

        // 5. 顯示原先被隱藏的地板、平台和武器 UI
        if (ground) ground.setVisible(true);
        if (platforms) platforms.setVisible(true);
        if (typeof setWeaponUIVisible === 'function') {
            setWeaponUIVisible(true);
        }

        // 6. 釋放超級震撼的「冥王炮」特效！
        const plutoGfx = scene.add.graphics();
        plutoGfx.setDepth(10002);
        plutoGfx.fillStyle(0x9400d3, 0.9); // 暗紫色能量波
        plutoGfx.fillRect(0, 0, scene.cameras.main.width, scene.cameras.main.height);

        // 強烈閃光與地震震動
        scene.cameras.main.flash(600, 148, 0, 211); // 紫色閃光
        scene.cameras.main.shake(1200, 0.04); // 激烈晃動 1.2 秒

        // 能量淡出並銷毀 Graphics
        scene.tweens.add({
            targets: plutoGfx,
            alpha: 0,
            duration: 1000,
            ease: 'Power2',
            onComplete: () => {
                plutoGfx.destroy();
            }
        });

        // 7. 直接對顏王Yeah 造成 99999 毀滅性傷害，逆轉戰局！
        handleYeahHit(scene, null, 0, 0, 99999, null, null);
    };
