                    0% { text-shadow: 0 0 12px #ff00ff, 0 -5px 18px #9400d3, 0 -10px 28px #8a2be2, 0 -15px 45px #4b0082; }
                    50% { text-shadow: 0 0 20px #ff00ff, 0 -8px 25px #9400d3, 0 -15px 35px #8a2be2, 0 -22px 60px #4b0082; }
